examples.setupTemplate:
val state = rememberMonarchGanttTimelineState(
    initialStart = {{defaultStart|millis}},
    initialZoom = MonarchGanttTimelineZoom.Quarter,
)
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag("en-GB")) }
}

examples.setup:
val state = rememberMonarchGanttTimelineState(
    initialStart = 1_767_225_600_000L,
    initialZoom = MonarchGanttTimelineZoom.Quarter,
)
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag("en-GB")) }
}

val jan1 = 1_767_225_600_000L
val day = 86_400_000L
var items by remember {
    mutableStateOf(listOf(MonarchRoadmapItem("p3", "Help center search", start = jan1 + 32 * day, end = jan1 + 119 * day, health = MonarchRoadmapHealth.AtRisk)))
}
val state = rememberMonarchGanttTimelineState(initialView = MonarchGanttTimelineView.List)

examples.code:
@OptIn(ExperimentalMonarchApi::class)
MonarchRoadmap(
    items = items,
    previousIcon = {},
    nextIcon = {},
    state = state,
    today = null,
    toolbar = false,
    onChange = { item, dates ->
        items = items.map {
            if (it.id != item.id) it else MonarchRoadmapItem(it.id, it.label, dates.start, dates.end, health = it.health)
        }
        // The app saves item.id with dates.start and dates.end here.
    },
)
